def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def solve():
    solutions = []
    # Search for p1, p2, p3 such that p1 > p2 > p3 > 0 and lcm(p1, p2, p3) divides p1+p2+p3
    # We also need p1+p2+p3 to be a multiple of the lcm.
    # Since p1+p2+p3 < 3*p1 and p1 <= lcm, p1+p2+p3 < 3*lcm.
    # So p1+p2+p3 = lcm or 2*lcm.
    for p1 in range(1, 100):
        for p2 in range(1, p1):
            for p3 in range(1, p2):
                L = lcm(p1, lcm(p2, p3))
                S = p1 + p2 + p3
                if S % L == 0:
                    solutions.append((p1, p2, p3, L, S))
    return solutions

