def find_rational_points(a1, C, max_val):
    # (a1+a2 + a1*a2*(1-C))^2 - 4*a1*a2*(a1+a2) = y^2
    # For a1=1, C=11: (1+a2-10a2)^2 - 4*a2*(1+a2) = (1-9a2)^2 - 4a2 - 4a2^2
    # = 81a2^2 - 18a2 + 1 - 4a2 - 4a2^2 = 77a2^2 - 22a2 + 1
    # We want to find rational a2 = p/q
    for q in range(1, max_val):
        for p in range(1, max_val):
            val = 77 * (p/q)**2 - 22 * (p/q) + 1
            if val > 0:
                sqrt_val = val**0.5
